    public function search(User $user, string $query): array
    {
        $normalize = fn (string $text) => preg_replace('/[\s\x{200C}]+/u', ' ', mb_strtolower(trim($text)));
        $stop = ['چطور', 'کجاست', 'کجا', 'چیه', 'چیست', 'میخوام', 'می‌خوام', 'کنم', 'بکنم', 'هست', 'است', 'برای', 'این', 'اون'];
        $words = array_values(array_filter(explode(' ', $normalize($query)), fn ($word) => mb_strlen($word) >= 3 && ! in_array($word, $stop, true)));
        $scored = collect(self::ENTRIES)->map(function (array $entry, string $key) use ($words, $normalize) {
            $haystack = $normalize($entry[0].' '.$entry[1]);
            $score = collect($words)->sum(fn ($word) => str_contains($haystack, $word) ? (str_contains($normalize($entry[0]), $word) ? 3 : 1) : 0);
            return ['key' => $key, 'score' => $score, 'entry' => $entry];
        })->filter(fn ($row) => $row['score'] > 0)->sortByDesc('score')->take(3)->values();
        $navigation = new AssistantNavigationCatalog;
        $matches = $scored->map(fn ($row) => [
            'title' => $row['entry'][0], 'where' => $row['entry'][2], 'what' => $row['entry'][3],
            'page' => $row['entry'][4] && $navigation->destination($user, $row['entry'][4]) ? $row['entry'][4] : null,
        ])->all();
        if ($matches === []) {
            return ['model' => ['matches' => [], 'available_topics' => collect(self::ENTRIES)->map(fn ($entry) => $entry[0])->values()->all()], 'presentation' => null];
        }
        $best = $matches[0];

        return [
            'model' => ['matches' => $matches],
            'presentation' => ['type' => 'record', 'title' => 'راهنما · '.$best['title'],
                'fields' => ['کجاست' => $best['where'], 'چه کار می‌کند' => $best['what']],
                'action' => $best['page'] ? ['page' => $best['page'], 'label' => 'رفتن به «'.$best['title'].'»'] : null],
        ];
    }
}
